#include "hwm/planner.hpp"
#include <iostream>
using namespace hwm;
int main(int argc,char**argv){uint64_t budget=argc>1?std::stoull(argv[1]):10000;BattleState s;s.battle_id="demo";s.state_seq=1;s.phase=Phase::Combat;s.width=12;s.height=10;s.protocol_ready=true;s.recommendation_safe=true;Entity a;a.uid=1;a.side=Side::Player;a.anchor={1,4};a.count=45;a.top_unit_hp=18;a.max_hp_per_unit=18;a.attack=14;a.defense=10;a.min_damage=3;a.max_damage=5;a.speed=5;a.shots=8;Entity b=a;b.uid=2;b.side=Side::Pve;b.anchor={8,4};b.count=50;b.attack=12;b.defense=12;b.shots=0;s.entities={a,b};s.active_entity_uid=1;s.side_to_act=Side::Player;Planner p({budget,12,12,1.4,42});auto r=p.plan(s);std::cout<<"budget="<<budget<<" elapsed_ms="<<r.elapsed_ms<<" simulations="<<r.simulations<<" nodes="<<r.nodes<<" sims_per_sec="<<(1000.0*r.simulations/std::max(0.001,r.elapsed_ms))<<"\n"<<"best="<<to_json(r.best.action)<<" p_win="<<r.best.p_win<<" score="<<r.best.score<<" visits="<<r.best.visits<<"\n";}
